using LibraryManagement.Application.DTOs;using LibraryManagement.Application.Services.Base;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;
namespace LibraryManagement.Controllers;[Authorize]public class BorrowingsController(IBorrowingService service):Controller{public async Task<IActionResult>Index()=>View(await service.GetAllAsync());public async Task<IActionResult>Details(string uuid){var x=await service.GetDetailsAsync(uuid);return x is null?NotFound():View(x);}[HttpGet]public async Task<IActionResult>Create(){await Lists();return View(new BorrowingCreateDto{BorrowDate=DateTime.Today,ReturnDate=DateTime.Today});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(BorrowingCreateDto dto){if(ModelState.IsValid)try{await service.AddAsync(dto);return RedirectToAction(nameof(Index));}catch(InvalidOperationException e){ModelState.AddModelError("",e.Message);}await Lists();return View(dto);}[HttpGet]public async Task<IActionResult>Edit(string uuid){var x=await service.GetForUpdateAsync(uuid);if(x is null)return NotFound();await Lists();return View(x);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(BorrowingUpdateDto dto){if(ModelState.IsValid)try{await service.UpdateAsync(dto);return RedirectToAction(nameof(Index));}catch(InvalidOperationException e){ModelState.AddModelError("",e.Message);}await Lists();return View(dto);}[HttpGet]public async Task<IActionResult>Delete(string uuid){var x=await service.GetDetailsAsync(uuid);return x is null?NotFound():View(x);}[HttpPost,ActionName("Delete"),ValidateAntiForgeryToken]public async Task<IActionResult>DeleteConfirmed(string uuid){await service.DeleteAsync(uuid);return RedirectToAction(nameof(Index));}async Task Lists(){ViewBag.Customers=new SelectList(await service.GetCustomersAsync(),"Id","Name");ViewBag.Books=new SelectList(await service.GetBooksAsync(),"Id","Title");}}
